from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            components.append(comp)
    if components:
        largest = max(map(len, components))
        smallest = min(map(len, components))
        for comp in components:
            color = 8 if len(comp) == largest else (7 if len(comp) == smallest else 0)
            if color:
                for r, c in comp:
                    out[r][c] = color
    return out
